import { CSPProvider } from "@/registry/erbium/ui/csp-provider";
import { OverlayProvider } from "@/registry/erbium/ui/overlay-provider";
import { Toaster } from "@/registry/erbium/ui/toast";
import type { ReactNode } from "react";

export const ShowcaseProviders = ({
  children,
  toast = false,
}: {
  children?: ReactNode;
  toast?: boolean;
}) => (
  <CSPProvider disableStyleElements>
    <OverlayProvider>
      {children}
      {toast && <Toaster />}
    </OverlayProvider>
  </CSPProvider>
);

export const ShowcaseSurface = ({ children }: { children?: ReactNode }) => (
  <div
    data-slot="component-preview"
    className="relative isolate mx-auto flex min-h-64 w-full min-w-0 max-w-3xl items-center justify-center gap-section p-5 font-sans text-foreground contain-layout sm:p-8 [&>.min-w-72.max-w-2xl]:flex [&>.min-w-72.max-w-2xl]:flex-col [&>.min-w-72.max-w-2xl]:items-center [&>.min-w-72.max-w-2xl]:justify-center"
  >
    {children}
  </div>
);

import { Badge } from "@/registry/erbium/ui/badge";

const SpinnerBadge = () => (
  <div className="flex items-center gap-group [--radius:1.2rem]">
    <Badge loading>Syncing</Badge>
    <Badge variant="secondary" loading>
      Updating
    </Badge>
    <Badge variant="outline" loading>
      Processing
    </Badge>
  </div>
);

export default SpinnerBadge;

import { Button } from "@/registry/erbium/ui/button";

const SpinnerButton = () => (
  <div className="flex flex-col items-center gap-group">
    <Button loading size="sm">
      Loading...
    </Button>
    <Button variant="outline" loading size="sm">
      Please wait
    </Button>
    <Button variant="secondary" loading size="sm">
      Processing
    </Button>
  </div>
);

export default SpinnerButton;

import { Item, ItemContent, ItemMedia, ItemTitle } from "@/registry/erbium/ui/item";
import { Spinner } from "@/registry/erbium/ui/spinner";

const SpinnerDemo = () => (
  <div className="flex w-full max-w-xs flex-col gap-group [--radius:1rem]">
    <Item variant="card">
      <ItemMedia>
        <Spinner />
      </ItemMedia>
      <ItemContent>
        <ItemTitle className="line-clamp-1">Processing payment...</ItemTitle>
      </ItemContent>
      <ItemContent className="flex-none justify-end">
        <span className="text-caption tabular-nums">$100.00</span>
      </ItemContent>
    </Item>
  </div>
);

export default SpinnerDemo;

import { Button } from "@/registry/erbium/ui/button";
import {
  Empty,
  EmptyContent,
  EmptyDescription,
  EmptyHeader,
  EmptyMedia,
  EmptyTitle,
} from "@/registry/erbium/ui/empty";
import { Spinner } from "@/registry/erbium/ui/spinner";

const SpinnerEmpty = () => (
  <Empty className="w-full">
    <EmptyHeader>
      <EmptyMedia variant="icon">
        <Spinner />
      </EmptyMedia>
      <EmptyTitle>Processing your request</EmptyTitle>
      <EmptyDescription>
        Please wait while we process your request. Do not refresh the page.
      </EmptyDescription>
    </EmptyHeader>
    <EmptyContent>
      <Button variant="outline" size="sm">
        Cancel
      </Button>
    </EmptyContent>
  </Empty>
);

export default SpinnerEmpty;

import { Icon } from "@/registry/erbium/ui/icon";

import {
  InputGroup,
  InputGroupAddon,
  InputGroupButton,
  InputGroupInput,
  InputGroupTextarea,
} from "@/registry/erbium/ui/input-group";
import { Spinner } from "@/registry/erbium/ui/spinner";

const SpinnerInputGroup = () => (
  <div className="flex w-full max-w-md flex-col gap-group">
    <InputGroup>
      <InputGroupInput placeholder="Send a message..." disabled />
      <InputGroupAddon align="inline-end">
        <Spinner />
      </InputGroupAddon>
    </InputGroup>
    <InputGroup>
      <InputGroupTextarea placeholder="Send a message..." disabled />
      <InputGroupAddon align="block-end">
        <Spinner /> Validating...
        <InputGroupButton className="ml-auto" variant="default">
          <Icon name="arrow-up-01" />
          <span className="sr-only">Send</span>
        </InputGroupButton>
      </InputGroupAddon>
    </InputGroup>
  </div>
);

export default SpinnerInputGroup;

import { Spinner } from "@/registry/erbium/ui/spinner";

const SpinnerSize = () => (
  <div className="flex items-center gap-section">
    <Spinner className="size-3" />
    <Spinner className="size-4" />
    <Spinner className="size-6" />
    <Spinner className="size-8" />
  </div>
);

export default SpinnerSize;

